const sharp=require('sharp');
const fs=require('fs');
const path=require('path');
(async()=>{
  const kok='ios/Runner/Assets.xcassets/AppIcon.appiconset';
  const json=JSON.parse(fs.readFileSync(path.join(kok,'Contents.json'),'utf8'));
  let hata=0;
  for(const img of json.images){
    if(!img.filename) continue;
    const yol=path.join(kok,img.filename);
    if(!fs.existsSync(yol)){ console.log('EKSIK: '+img.filename); hata++; continue; }
    const m=await sharp(yol).metadata();
    const [w,h]=img.size.split('x').map(Number);
    const olcek=Number(img.scale.replace('x',''));
    const bekW=Math.round(w*olcek), bekH=Math.round(h*olcek);
    const ok = m.width===bekW && m.height===bekH;
    if(!ok){ console.log('BOYUT HATASI: '+img.filename+' -> '+m.width+'x'+m.height+' (beklenen '+bekW+'x'+bekH+')'); hata++; }
  }
  console.log(hata===0 ? 'Tum iOS ikonlari dogru boyutta.' : hata+' sorun bulundu.');
})();
